@@ -0,0 +1,39 @@
+package hotel.notifications;
+
+import hotel.documents.ReservationReceipt;
+import hotel.documents.TextFormat;
+import hotel.messages.EmailSender;
+import hotel.reservations.Reservation;
+
+/** Housekeeping (governança) prepares the room, so it hears about confirmations and cancellations. */
+public final class HousekeepingNotifications implements ReservationListener {
+
+    static final String ADDRESS = "governanca@pousadamarealta.com.br";
+
+    private final EmailSender emailSender;
+
+    public HousekeepingNotifications(EmailSender emailSender) {
+        this.emailSender = emailSender;
+    }
+
+    @Override
+    public void confirmed(Reservation reservation, ReservationReceipt receipt) {
+        emailSender.send(
+                ADDRESS,
+                "Reserva confirmada - quarto " + reservation.roomNumber(),
+                "Reserva " + reservation.id() + " confirmada para o quarto " + reservation.roomNumber() + ".\n"
+                        + "Entrada: " + TextFormat.date(reservation.checkIn()) + "\n"
+                        + "Saída: " + TextFormat.date(reservation.checkOut()) + "\n"
+                        + "Hóspedes: " + reservation.guests() + "\n");
+    }
+
+    @Override
+    public void confirmedReservationCancelled(Reservation reservation) {
+        emailSender.send(
+                ADDRESS,
+                "Reserva cancelada - quarto " + reservation.roomNumber(),
+                "A reserva " + reservation.id() + " do quarto " + reservation.roomNumber() + " foi cancelada.\n"
+                        + "O quarto ficou livre de " + TextFormat.date(reservation.checkIn())
+                        + " a " + TextFormat.date(reservation.checkOut()) + ".\n");
+    }
+}
diff --git a/src/main/java/hotel/notifications/ReservationListener.java b/src/main/java/hotel/notifications/ReservationListener.java
new file mode 100644
index 0000000..2ea33bb
--- /dev/null
+++ b/src/main/java/hotel/notifications/ReservationListener.java
@@ -0,0 +1,22 @@
+package hotel.notifications;
+
+import hotel.documents.ReservationReceipt;
+import hotel.reservations.Reservation;
+
+/**
+ * Someone who wants to know what happens to reservations. Implement only the events you care about and
+ * register the listener in {@code Hotel}; the reservation service itself never needs to change.
+ */
+public interface ReservationListener {
+
+    /** A pending reservation was paid and is now confirmed. */
+    default void confirmed(Reservation reservation, ReservationReceipt receipt) {
+    }
+
+    /**
+     * A reservation that had been confirmed was cancelled. {@link Reservation#refund()} says how much goes
+     * back to the guest (possibly zero). Reservations cancelled while still pending do not raise this.
+     */
+    default void confirmedReservationCancelled(Reservation reservation) {
+    }
+}
diff --git a/src/main/java/hotel/notifications/ReservationListeners.java b/src/main/java/hotel/notifications/ReservationListeners.java
new file mode 100644
index 0000000..2802df0
--- /dev/null
+++ b/src/main/java/hotel/notifications/ReservationListeners.java
@@ -0,0 +1,18 @@
+package hotel.notifications;
+
+import hotel.messages.EmailSender;
+import java.util.List;
+
+/** The listeners the inn has today. To add or remove a recipient, change this list. */
+public final class ReservationListeners {
+
+    private ReservationListeners() {
+    }
+
+    public static List<ReservationListener> standard(EmailSender emailSender) {
+        return List.of(
+                new GuestNotifications(emailSender),
+                new HousekeepingNotifications(emailSender),
+                new FinanceNotifications(emailSender));
+    }
+}
